/** Actual Source cache timing, physical input and receiver isolation across every canonical state. */
public final class ScreenJoinedPowerLegacyChecks {
 private static int strength,reads;private static Block PROBE;
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();PROBE=new Block(Material.ROCK){@Override public boolean shouldCheckWeakPower(IBlockState state,IBlockAccess world,BlockPos pos,EnumFacing side){return false;}@Override public int getWeakPower(IBlockState state,IBlockAccess world,BlockPos pos,EnumFacing side){reads++;return strength;}};net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityAnimatedScreenSelector.class,new ResourceLocation("minecraft:screen_joined_power_reference"));JsonArray output=new JsonArray();for(String id:ScreenFamilyLegacyChecks.IDS){BlockAnimatedScreenSelector block=null;for(Block candidate:ModBlocks.BLOCKS)if(candidate.getRegistryName().getResourcePath().equals(id))block=(BlockAnimatedScreenSelector)candidate;for(IBlockState state:block.getBlockState().getValidStates())for(int mode=0;mode<3;mode++)for(boolean inverted:new boolean[]{false,true}){NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);TileEntityAnimatedScreenSelector[] tiles=new TileEntityAnimatedScreenSelector[2];BlockPos pos=new BlockPos(0,80,0);for(int i=0;i<2;i++){TileEntityAnimatedScreenSelector tile=(TileEntityAnimatedScreenSelector)block.createNewTileEntity(null,0);tile.activation.mode=mode;tile.setRedstoneInverted(inverted);if(i==1){DisplayJoinGeometry.Basis basis=DisplayJoinGeometry.basis(tiles[0],state);pos=tiles[0].getPos().add(basis.steps[0]);}world.states.put(pos,state);world.tiles.put(pos,tile);tile.setWorld(world);tile.setPos(pos);world.states.put(pos.up(),PROBE.getDefaultState());tiles[i]=tile;}JsonArray phases=new JsonArray();strength=0;phases.add(sample(tiles));strength=7;phases.add(sample(tiles));world.time++;phases.add(sample(tiles));strength=12;tiles[1].localInputChanged();phases.add(sample(tiles));tiles[0].setChannelLevel(15);strength=0;tiles[0].localInputChanged();phases.add(sample(tiles));tiles[1].invalidate();world.tiles.remove(tiles[1].getPos());strength=5;phases.add(sample(new TileEntityAnimatedScreenSelector[]{tiles[0]}));JsonObject row=new JsonObject();row.addProperty("id",id);row.addProperty("meta",block.getMetaFromState(state));row.addProperty("mode",mode);row.addProperty("inverted",inverted);row.add("phases",phases);output.add(row);}}String text=output.toString();java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");StringBuilder digest=new StringBuilder();for(byte b:hash.digest(text.getBytes("UTF-8")))digest.append(String.format("%02x",b&255));if(!digest.toString().equals("29e237d5369446fbf21212fed41a3757a1ef8d18e8a0b1499a6e2ae77e11382d"))throw new AssertionError("Actual joined power changed "+digest);JsonObject root=new JsonObject();root.addProperty("sha256",digest.toString());root.add("cases",output);java.nio.file.Path path=java.nio.file.Paths.get("build/test-artifacts/screen-joined-power-reference.json");java.nio.file.Files.createDirectories(path.getParent());java.nio.file.Files.write(path,root.toString().getBytes("UTF-8"));System.out.println("Actual Screen joined power reference PASS cases="+output.size()+" sha256="+digest);}
 private static JsonArray sample(TileEntityAnimatedScreenSelector[] tiles){JsonArray phase=new JsonArray();for(TileEntityAnimatedScreenSelector tile:tiles){JsonArray value=new JsonArray();value.add(JoinedDisplayPower.level(tile));value.add(tile.getSignalLevel());phase.add(value);}return phase;}
}
